function resolveAriaHidden(ariaHidden?: boolean, ariaHiddenAttr?: IconProps["aria-hidden"]) {
  if (ariaHidden !== undefined) return ariaHidden;
  if (ariaHiddenAttr === undefined) return undefined;
  return ariaHiddenAttr === true || ariaHiddenAttr === "true";
}

