type ActionIconComponent = ComponentType<IconProps>;

export const LOCAL_ENVIRONMENT_ACTION_ICON_OPTIONS: ReadonlyArray<{
  value: WorktreeEnvironmentActionIcon;
  label: string;
  icon: ActionIconComponent;
}> = [
  { value: "tool", label: "Tool", icon: ToolActionIcon },
  { value: "run", label: "Run", icon: RunActionIcon },
  { value: "debug", label: "Debug", icon: DebugActionIcon },
  { value: "test", label: "Test", icon: TestActionIcon },
];

export function getLocalEnvironmentActionIconOption(icon: WorktreeEnvironmentActionIcon | null) {
  return (
    LOCAL_ENVIRONMENT_ACTION_ICON_OPTIONS.find((option) => option.value === icon) ??
    LOCAL_ENVIRONMENT_ACTION_ICON_OPTIONS[0]
  );
}

export function LocalEnvironmentActionIcon({
  icon,
  className,
}: {
  icon: WorktreeEnvironmentActionIcon | null;
  className?: string;
}) {
  const option = getLocalEnvironmentActionIconOption(icon);
  const Icon = option.icon;
  return <Icon className={cn("icon-sm", className)} />;
}

