export function ActivitySpinnerIcon({
  as: Wrapper = "span",
  className,
  containerClassName,
  icon: Icon = LoadingIcon,
  animationDurationMs,
}: IconProps & {
  as?: ElementType;
  containerClassName?: string;
  icon?: ComponentType<IconProps>;
  animationDurationMs?: number;
}) {
  const reducedMotion = useResolvedReducedMotion();
  const [animationDelay] = useState(() => `-${Date.now() % 1_000}ms`);

  return (
    <Wrapper
      data-activity-spinner="true"
      className={cn(
        !reducedMotion && "animate-spin",
        "inline-flex h-fit w-fit shrink-0 items-center justify-center leading-none contain-layout contain-paint contain-style",
        containerClassName,
      )}
      style={{
        animationDelay,
        animationDuration:
          animationDurationMs === undefined ? undefined : `${animationDurationMs}ms`,
      }}
      aria-hidden="true"
    >
      <Icon className={className ?? "icon-sm"} />
    </Wrapper>
  );
}

