function renderFileTabIconNode(node: FileTabIconNode, index: number): ReactNode {
  return createElement(
    node.type,
    { ...node.props, key: index },
    node.children?.map(renderFileTabIconNode),
  );
}

export interface FileTabIconSvgProps extends Omit<SVGProps<SVGSVGElement>, "children"> {
  icon: FileTabIconName;
}

export function FileTabIconSvg({ icon, ...props }: FileTabIconSvgProps) {
  const { nodes, ...svgProps } = FILE_TAB_ICON_DEFINITIONS[icon];

  return (
    <svg aria-hidden="true" data-file-tab-icon={icon} {...svgProps} {...props}>
      {nodes.map(renderFileTabIconNode)}
    </svg>
  );
}

